void SetAppWindowIcon(GLFWwindow* window) {
    GLFWimage images[4];
    images[0].width = 16;
    images[0].height = 16;
    images[0].pixels = const_cast<unsigned char*>(ICON_16_RGBA);

    images[1].width = 32;
    images[1].height = 32;
    images[1].pixels = const_cast<unsigned char*>(ICON_32_RGBA);

    images[2].width = 48;
    images[2].height = 48;
    images[2].pixels = const_cast<unsigned char*>(ICON_48_RGBA);

    images[3].width = 256;
    images[3].height = 256;
    images[3].pixels = const_cast<unsigned char*>(ICON_256_RGBA);

    glfwSetWindowIcon(window, 4, images);
}

